eval("__webpack_require__.r(__webpack_exports__);\n/* harmony export */ __webpack_require__.d(__webpack_exports__, {\n/* harmony export */   projects: () => (/* binding */ projects)\n/* harmony export */ });\nconst projects = [\n    {\n        id: \"pemira-e-voting\",\n        title: \"Pemira FTUI 2025 E-Voting System\",\n        role: \"Tech Lead\",\n        duration: \"Dec 2025\",\n        category: \"web\",\n        summary: \"A web-based voting platform for the Faculty of Engineering student election at Universitas Indonesia. Built to handle high-concurrency traffic with verified votes.\",\n        context: `Built for the annual FTUI Student Election, which had to serve ~3,200 eligible voters in a 6-hour window. The legacy system was a Google Form, which couldn't enforce one-vote-per-student or surface live turnout.`,\n        problem: \"How do you build a voting system that is auditable, one-vote-per-student, and resilient to peak traffic from a campus that hits the site between classes?\",\n        approach: \"Split the system into a Remix frontend (server-rendered, fast first paint) and an Express.js backend (complex vote-counting logic). Containerized with Docker, deployed on Dokploy. Identity verification happened against a pre-loaded student list, votes were stored append-only with timestamps.\",\n        result: \"Served 2,900+ unique users, processed 2,600+ verified votes — about 90% turnout, the highest in FTUI Pemira history. No data loss, no double-voting incidents.\",\n        stack: [\n            \"Remix\",\n            \"Express.js\",\n            \"Tailwind CSS\",\n            \"Docker\",\n            \"Dokploy\",\n            \"PostgreSQL\"\n        ],\n        metrics: [\n            {\n                label: \"Unique users\",\n                value: \"2,900+\"\n            },\n            {\n                label: \"Verified votes\",\n                value: \"2,600+\"\n            },\n            {\n                label: \"Turnout\",\n                value: \"~90%\"\n            },\n            {\n                label: \"Peak window\",\n                value: \"6 hours\"\n            }\n        ],\n        highlights: [\n            \"Led a 4-person team across frontend, backend, and deployment\",\n            \"Containerized the entire stack; redeploys in under 90 seconds\",\n            \"One-vote-per-student enforced via pre-loaded student registry + session-bound tokens\"\n        ],\n        learnings: \"The interesting part was not the voting logic — it was the traffic pattern. People vote in clusters between classes, so the system has to be ready for 200 concurrent writes at 11:55 sharp. That shaped the whole architecture.\",\n        featured: true\n    },\n    {\n        id: \"common-source-amplifier\",\n        title: \"Common-Source Amplifier — 130nm Characterization\",\n        role: \"Coursework (Independent)\",\n        duration: \"Mar 2026\",\n        category: \"semiconductor\",\n        summary: \"Designed and characterized a common-source amplifier using open-source EDA tools targeting the Skywater 130nm PDK. Bridged textbook amplifier theory with real transistor-level design.\",\n        context: \"A self-directed coursework project to understand analog design at the layout level — not just simulation. The goal was to take a design from schematic through to a clean GDS-ready layout.\",\n        problem: \"How does load choice (resistive vs diode-connected vs current-source) change gain, bandwidth, and headroom? What does it look like in silicon?\",\n        approach: \"Used Xschem for schematic entry, Ngspice for characterization sweeps. Ran DC operating-point analysis on NMOS/PMOS devices to size them for the target gain, then built the amplifier with three load configurations and compared their trade-offs.\",\n        result: \"Confirmed textbook behavior in simulation: current-source load gave highest gain, resistive load gave most headroom, diode-connected gave the most compact layout. A working schematic in Xschem + characterization plots in Ngspice.\",\n        stack: [\n            \"Xschem\",\n            \"Ngspice\",\n            \"Skywater 130nm PDK\",\n            \"NMOS/PMOS characterization\"\n        ],\n        highlights: [\n            \"Ran DC sweeps across Vov, Vds, and W/L to find the saturation region\",\n            \"Compared three load configurations on the same transistor size\",\n            \"All open-source tooling — no paid EDA licenses\"\n        ],\n        learnings: 'Reading about \"current-source load gives more gain\" in a textbook is one thing. Sweeping it in Ngspice and watching the gain plot curve up is a different kind of knowing.'\n    },\n    {\n        id: \"selamat-sentosa-battery-charger\",\n        title: \"Selamat Sentosa — Li-ion Battery Charger with Auto-Cutoff\",\n        role: \"Electronics Project Lead\",\n        duration: \"Aug 2025\",\n        category: \"hardware\",\n        summary: \"A smart Li-ion battery charger that cuts off charging at 4.2V using discrete analog blocks. No microcontroller, just an IC 555 timer, op-amps, Zener diodes, and transistors.\",\n        context: 'A class project to design a battery charger that does not overcharge. The brief was \"design it without firmware.\" That constraint forced real analog thinking.',\n        problem: \"How do you safely stop a charging current at 4.2V using only hardware?\",\n        approach: \"Three blocks: (1) IC 555 in astable mode for pulse charging, (2) op-amp + Zener voltage detector that compares battery voltage to a 4.2V reference, (3) NPN cutoff transistor that pulls the 555 reset pin to ground when the threshold is crossed.\",\n        result: \"Functional circuit on breadboard. Cutoff engaged within \\xb150mV of target. The system runs in a tight loop — pulse, sense, decide, cut.\",\n        stack: [\n            \"IC 555 Timer\",\n            \"Op-Amps (LM358)\",\n            \"Zener Diodes\",\n            \"NPN Transistors\",\n            \"Breadboard\"\n        ],\n        highlights: [\n            \"Cutoff at 4.2V \\xb1 50mV\",\n            \"Pulse charging with adjustable duty cycle via 555 timing components\",\n            \"Zero software, zero microcontroller\"\n        ],\n        learnings: \"The first version had hysteresis problems — the cutoff would oscillate near the threshold. Adding a small amount of positive feedback on the comparator fixed it. That oscillation is something you only see by building.\"\n    },\n    {\n        id: \"exertion-2025\",\n        title: \"EXERTION 2025 — National Competition Platform\",\n        role: \"Tech Lead\",\n        duration: \"May 2025 – Jul 2025\",\n        category: \"web\",\n        summary: \"A national-scale competition platform with three sub-events: UI/UX Design, Business Innovation, and Exermind (an online exam with tab-switch detection).\",\n        context: \"EXERTION is the annual EXERCISE FTUI 2025 national competition. The brief was a single platform that could host multiple event types, with role-based access for participants, judges, and admins.\",\n        problem: \"Three event types with very different UX needs: open-ended submissions, pitch decks, and timed online exams with integrity checks.\",\n        approach: \"Next.js frontend with Supabase for auth, database, and real-time updates. The Exermind exam module was the hardest part — autosave, randomized questions, a server-side timer, and tab-switch detection that pauses the exam when the participant leaves the window.\",\n        result: \"Shipped on time, ran all three sub-events in parallel, served participants from multiple universities. The tab-switch detection worked as designed — flagged several attempted violations during the actual exam.\",\n        stack: [\n            \"Next.js\",\n            \"Supabase\",\n            \"Tailwind CSS\",\n            \"TypeScript\",\n            \"PostgreSQL\"\n        ],\n        highlights: [\n            \"Exermind exam: autosave, randomized questions, tab-switch detection\",\n            \"Role-based access: participants, judges, admins\",\n            \"Real-time submission status updates\"\n        ],\n        learnings: \"Tab-switch detection sounds simple until you try it — visibilitychange events, focus events, blur events, all firing in different combinations. The fix was a server-side heartbeat: the client pings every 5 seconds, and the server infers focus from that.\"\n    },\n    {\n        id: \"iot-water-dispenser\",\n        title: \"IoT Smart Water Dispenser with Real-Time Monitoring\",\n        role: \"Firmware & Cloud Developer\",\n        duration: \"Jun 2025\",\n        category: \"iot\",\n        summary: \"An automated water dispenser that detects cup presence and tank level using ultrasonic sensors on an ESP32, with real-time monitoring over MQTT.\",\n        context: \"A practical project: replace the manual gallon dispenser in the lab with one that pours when a cup is placed, and reports usage to a dashboard.\",\n        problem: \"How do you reliably detect a cup under a spout, and report water level without a cloud bill per sensor?\",\n        approach: \"ESP32 with two HC-SR04 ultrasonic sensors — one pointed at the cup platform, one at the tank. C/C++ firmware on the ESP32 processes the sensor data and publishes to MQTT. A small Node.js bridge pushes to a dashboard.\",\n        result: \"Working system. Cup detection reliable within 2cm. Tank level tracked over time. Real-time monitoring on a simple dashboard.\",\n        stack: [\n            \"ESP32\",\n            \"C/C++\",\n            \"MQTT\",\n            \"HC-SR04 Ultrasonic Sensors\",\n            \"Node.js\"\n        ],\n        highlights: [\n            \"Cup detection reliable within 2cm\",\n            \"MQTT-based telemetry — no per-message cloud cost\",\n            \"Tank level tracked over time, alertable at low level\"\n        ],\n        learnings: 'Ultrasonic sensors have a blind zone — they cannot read closer than ~2cm. The first version thought every cup was \"already gone\" because the sensor was too close. Mounting it higher fixed it.'\n    },\n    {\n        id: \"tis-exercise-collab\",\n        title: \"TIS \\xd7 EXERCISE FTUI 2025 Collaboration Site\",\n        role: \"Tech Lead\",\n        duration: \"May 2025 – Jun 2025\",\n        category: \"web\",\n        summary: \"A joint web presence for the partnership between TIS FTUI 2025 and EXERCISE FTUI 2025, designed so non-technical contributors can update it.\",\n        context: \"Two student organizations wanted a single site for their joint activities. The challenge: build something the org members (mostly non-engineers) can actually maintain.\",\n        problem: \"How do you give content ownership to non-technical users without giving them access to break the codebase?\",\n        approach: \"Next.js frontend with a headless CMS backend. Editors get a familiar WYSIWYG interface; the build pipeline pulls content at build time. Performance stays static, content stays editable.\",\n        result: \"Shipped. Editors have published dozens of updates without engineering involvement. Site loads fast, passes Lighthouse, works on phones.\",\n        stack: [\n            \"Next.js\",\n            \"Tailwind CSS\",\n            \"Headless CMS\",\n            \"Static Site Generation\"\n        ],\n        highlights: [\n            \"Decoupled content from code via headless CMS\",\n            \"Editors can publish without touching the repo\",\n            \"Static output, fast on any connection\"\n        ]\n    }\n];\n//# sourceURL=[module]\n//# sourceMappingURL=data:application/json;charset=utf-8;base64,\n//# sourceURL=webpack-internal:///(ssr)/./src/data/projects.ts\n");

